def build():
    graph=json.loads((ROOT/'review/personalization-v2/data/graph.json').read_text(encoding='utf-8'));nodes=graph['nodes'];records={}
    for n in nodes:
        if n['level']=='L3_Knowledge':
            task=TASKS[n['course_id']][int(n['id'][-2:])-1]
            records[n['id']]={'goal':'能够独立完成并解释'+n['label']+'相关任务。','practice':task,'check':'独立完成上述任务，保留推导/代码/测量记录；改变一个条件复做，解释结果差异，由教师核验。'}
        elif n['level']=='L2_Course':records[n['id']]={'goal':'将本课程原理、分析和实践目标对应到具体任务。','practice':'从本课已评价知识点中选择优先项，用配套任务短测定位困难；仅有课程总分时先测评再定位。','check':'按知识点记录过程与复测结果，比较前后表现；不能用完成建议直接改分。'}
        else:records[n['id']]={'goal':'用支撑课程中的可观察任务检验该项毕业能力。','practice':'选择高贡献且证据充分的支撑课程，布置可展示分析、设计或验证过程的综合任务。','check':'使用明确量规核验过程、结果和反思；将低覆盖课程列为待补证据，不认定能力缺失。'}
    destination=ROOT/'review/teaching-reference';destination.mkdir(exist_ok=True)
    (destination/'reference.json').write_text(json.dumps({'version':'teaching-1','provenance':'authored_demo_reference','limitations':'编写的演示教学任务，不是真实学生错题、教师大纲或权威标准答案。','nodes':records},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Authored teaching tasks:',len(records))

if __name__=='__main__':build()
